create or replace function public.create_academy(p_name text,p_city text default null,p_state text default null,p_country text default 'India') returns uuid language plpgsql security invoker set search_path=public as $$ declare v_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.profiles where user_id=auth.uid() and role in ('coach','academy_admin','admin','super_admin')) then raise exception 'Coach account required'; end if; if not exists(select 1 from public.subscriptions where user_id=auth.uid() and plan_id='academy' and status in ('active','trialing')) then raise exception 'An active Academy plan is required'; end if; insert into public.academies(owner_user_id,name,city,state,country,status) values(auth.uid(),trim(p_name),nullif(trim(p_city),''),nullif(trim(p_state),''),nullif(trim(p_country),''),'active') returning id into v_id; insert into public.academy_memberships(academy_id,user_id,role,status) values(v_id,auth.uid(),'academy_admin','active') on conflict(academy_id,user_id) do update set role='academy_admin',status='active'; insert into public.academy_coach_seats(academy_id,coach_user_id,seat_type,activation_fee,monthly_fee) values(v_id,auth.uid(),'included',0,0) on conflict do nothing; update public.profiles set academy_id=v_id,coach_user_id=auth.uid(),role='academy_admin' where user_id=auth.uid(); return v_id; end; $$;
revoke all on function public.create_academy(text,text,text,text) from public,anon; grant execute on function public.create_academy(text,text,text,text) to authenticated;

create or replace function public.coach_connect_athlete(p_username text,p_academy_id uuid default null) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_athlete uuid; v_link uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.profiles where user_id=auth.uid() and role in ('coach','academy_admin')) then raise exception 'Coach access required'; end if; select user_id into v_athlete from public.profiles where lower(username)=lower(trim(p_username)) and role='athlete' limit 1; if v_athlete is null then raise exception 'Athlete username was not found'; end if; if v_athlete=auth.uid() then raise exception 'A coach cannot link their own account'; end if; if p_academy_id is not null and not private.user_is_academy_staff(p_academy_id) then raise exception 'Academy access denied'; end if; insert into public.coach_athlete_links(coach_user_id,athlete_user_id,academy_id,status) values(auth.uid(),v_athlete,p_academy_id,'active') on conflict(coach_user_id,athlete_user_id,academy_id) do update set status='active',updated_at=now() returning id into v_link; update public.profiles set coach_user_id=auth.uid(),academy_id=coalesce(p_academy_id,academy_id) where user_id=v_athlete and (coach_user_id is null or coach_user_id=auth.uid()); return v_link; end; $$;
revoke all on function public.coach_connect_athlete(text,uuid) from public,anon; grant execute on function public.coach_connect_athlete(text,uuid) to authenticated;

create or replace function public.academy_add_coach(p_username text) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_coach uuid; v_academy uuid; v_active integer; v_seat uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select id into v_academy from public.academies where owner_user_id=auth.uid() and status='active' order by created_at desc limit 1; if v_academy is null then raise exception 'Academy operator access required'; end if; select user_id into v_coach from public.profiles where lower(username)=lower(trim(p_username)) and role='coach' limit 1; if v_coach is null then raise exception 'Coach username was not found'; end if; select count(*) into v_active from public.academy_coach_seats where academy_id=v_academy and status='active'; if v_active>=2 then raise exception 'Both included coach seats are already in use. Additional coach seats require paid activation.'; end if; insert into public.academy_memberships(academy_id,user_id,role,status) values(v_academy,v_coach,'coach','active') on conflict(academy_id,user_id) do update set role='coach',status='active'; insert into public.academy_coach_seats(academy_id,coach_user_id,seat_type,activation_fee,monthly_fee,status) values(v_academy,v_coach,'included',0,0,'active') on conflict(academy_id,coach_user_id) do update set status='active',updated_at=now() returning id into v_seat; update public.profiles set academy_id=v_academy where user_id=v_coach; return v_seat; end; $$;
revoke all on function public.academy_add_coach(text) from public,anon; grant execute on function public.academy_add_coach(text) to authenticated;

create or replace function public.review_coach_approval(p_request_id uuid,p_status text,p_notes text default null) returns boolean language plpgsql security invoker set search_path=public as $$ declare r public.coach_approval_requests%rowtype; p public.profiles%rowtype; begin select * into r from public.coach_approval_requests where id=p_request_id and coach_user_id=auth.uid() and status='pending' for update; if not found then raise exception 'Approval request not found or already reviewed'; end if; if p_status not in ('approved','rejected') then raise exception 'Invalid review status'; end if; select * into p from public.profiles where user_id=r.athlete_user_id; if p_status='approved' then if r.request_type='belt_change' then insert into public.taekwondo_belt_history(athlete_user_id,coach_user_id,academy_id,previous_belt,new_belt,notes) values(r.athlete_user_id,auth.uid(),r.academy_id,p.belt,r.requested_value,p_notes); update public.profiles set belt=r.requested_value where user_id=r.athlete_user_id; elsif r.request_type='competition_weight_category' then insert into public.taekwondo_weight_category_decisions(athlete_user_id,coach_user_id,academy_id,athlete_weight_kg,category,notes) values(r.athlete_user_id,auth.uid(),r.academy_id,coalesce(r.athlete_weight_kg,p.weight_kg,0),r.requested_value,p_notes); update public.profiles set competition_weight_category=r.requested_value,competition_weight_category_updated_at=now() where user_id=r.athlete_user_id; end if; end if; update public.coach_approval_requests set status=p_status,reviewed_at=now(),notes=coalesce(p_notes,notes),updated_at=now() where id=p_request_id; insert into public.audit_logs(actor_user_id,action,entity_table,entity_id,metadata) values(auth.uid(),'coach_approval_'||p_status,'coach_approval_requests',p_request_id,jsonb_build_object('request_type',r.request_type,'athlete_user_id',r.athlete_user_id,'requested_value',r.requested_value)); return true; end; $$;
revoke all on function public.review_coach_approval(uuid,text,text) from public,anon; grant execute on function public.review_coach_approval(uuid,text,text) to authenticated;

create or replace function public.academy_add_coach(p_username text) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_coach uuid; v_academy uuid; v_active integer; v_seat uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select id into v_academy from public.academies where owner_user_id=auth.uid() and status='active' order by created_at desc limit 1; if v_academy is null then raise exception 'Academy operator access required'; end if; select user_id into v_coach from public.profiles where lower(username)=lower(trim(p_username)) and role='coach' limit 1; if v_coach is null then raise exception 'Coach username was not found'; end if; select count(*) into v_active from public.academy_coach_seats where academy_id=v_academy and status='active'; if v_active>=2 then raise exception 'Both included coach seats are already in use. Additional coach seats require paid activation.'; end if; insert into public.academy_memberships(academy_id,user_id,role,status) values(v_academy,v_coach,'coach','active') on conflict(academy_id,user_id) do update set role='coach',status='active'; insert into public.academy_coach_seats(academy_id,coach_user_id,seat_type,activation_fee,monthly_fee,status) values(v_academy,v_coach,'included',0,0,'active') on conflict(academy_id,coach_user_id) do update set status='active',updated_at=now() returning id into v_seat; update public.profiles set academy_id=v_academy where user_id=v_coach; return v_seat; end; $$;
